def minimum_valid_assignment_groups(nums):
    from collections import Counter
    counts=Counter(nums)
    for size in range(min(counts.values()),0,-1):
        total=0
        for count in counts.values():
            if count//size<count%size:break
            total+=(count+size)//(size+1)
        else:return total

